mapper.select:
        select
            min(valid_start_date) as requestStartDate,
            max(valid_end_date) as requestEndDate
        from
            b_marketing_data_valid_config
        where
          api_code = #{apiCode}
          and user_type = #{userType}
          and  valid_start_date <= #{statisticDate} and valid_end_date >= #{statisticDate} 
	      and is_del = 1
